import {test,expect} from '@playwright/test';
test('monthly quote uses plan price and adds fee',async({page})=>{
 await page.goto('/');
 const quote=page.locator('output[data-testid="quote"]');
 const notice=page.locator('p[data-testid="notice"]');
 await expect(quote).toHaveText('—'); await expect(notice).toHaveText('');
 await expect(page.getByLabel('Seats')).toHaveValue('2');
 await expect(page.getByLabel('Plan')).toHaveValue('basic');
 await expect(page.getByLabel('Annual')).not.toBeChecked();
 await expect(page.getByLabel('Terms')).not.toBeChecked();
 await page.getByLabel('Terms').check();
 await page.getByLabel('Seats').fill('1'); await page.getByLabel('Plan').selectOption('basic');
 await page.getByRole('button',{name:'Quote'}).click();
 await expect(quote).toHaveText('150'); await expect(notice).toHaveText('Ready');
 await page.getByLabel('Seats').fill('8'); await page.getByLabel('Plan').selectOption('pro');
 await page.getByRole('button',{name:'Quote'}).click();
 await expect(quote).toHaveText('1630'); await expect(notice).toHaveText('Ready');
 await page.getByLabel('Seats').fill('3');
 await page.getByRole('button',{name:'Quote'}).click();
 await expect(quote).toHaveText('630'); await expect(notice).toHaveText('Ready');
});

