import {test,expect} from '@playwright/test';
test('initial state and terms rejection preserve existing quote',async({page})=>{
 await page.goto('/');
 const quote=page.locator('output[data-testid="quote"]');
 const notice=page.locator('p[data-testid="notice"]');
 await expect(page.getByLabel('Seats')).toHaveValue('2');
 await expect(page.getByLabel('Plan')).toHaveValue('basic');
 await expect(page.getByLabel('Annual')).not.toBeChecked(); await expect(page.getByLabel('Terms')).not.toBeChecked();
 await expect(quote).toHaveText('—'); await expect(notice).toHaveText('');
 await page.getByRole('button',{name:'Quote'}).click();
 await expect(notice).toHaveText('Accept terms'); await expect(quote).toHaveText('—');
 await page.getByLabel('Terms').check(); await page.getByRole('button',{name:'Quote'}).click();
 await expect(quote).toHaveText('270'); await expect(notice).toHaveText('Ready');
 await page.getByLabel('Terms').uncheck(); await page.getByRole('button',{name:'Quote'}).click();
 await expect(notice).toHaveText('Accept terms'); await expect(quote).toHaveText('270');
});

import {test,expect} from '@playwright/test';
test('invalid seat values are rejected and preserve quote',async({page})=>{
 await page.goto('/');
 const quote=page.locator('output[data-testid="quote"]');
 const notice=page.locator('p[data-testid="notice"]');
 await page.getByLabel('Terms').check();
 for (const value of ['0','-1','1.5','9']) {
  await page.getByLabel('Seats').fill(value);
  await page.getByRole('button',{name:'Quote'}).click();
  await expect(notice).toHaveText('Seats must be an integer from 1 to 8');
  await expect(quote).toHaveText('—');
 }
 await page.getByLabel('Seats').fill('2'); await page.getByRole('button',{name:'Quote'}).click();
 await expect(quote).toHaveText('270'); await expect(notice).toHaveText('Ready');
 await page.getByLabel('Seats').fill('0'); await page.getByLabel('Terms').uncheck();
 await page.getByRole('button',{name:'Quote'}).click();
 await expect(notice).toHaveText('Seats must be an integer from 1 to 8');
 await expect(quote).toHaveText('270');
});

